 20→func newTestHandler(t *testing.T) (*Handler, string) {
 21→	t.Helper()
 22→	tmpVault := testutil.SetupTestVault(t)
 23→	v := &vault.Vault{Path: tmpVault}
 24→	logger := slog.New(slog.NewTextHandler(io.Discard, nil))
 25→	return New(v, logger), tmpVault
