112→			for tag, wantCount := range tt.wantTags {
113→				if got := tagCounts[tag]; got != wantCount {
114→					t.Errorf("tag %q count = %d, want %d", tag, got, wantCount)
115→				}
116→			}
117→			if len(tagCounts) != len(tt.wantTags) {
118→				t.Errorf("got %d tags, want %d. Tags: %v", len(tagCounts), len(tt.wantTags), tagCounts)
119→			}
120→		})
121→	}
122→}
