  1→package vault
  2→
  3→import (
  4→	"fmt"
  5→	"os"
  6→	"path/filepath"
  7→	"strings"
  8→)
  9→
 10→// MaxSearchResults limits the number of search results to prevent excessive output
 11→const MaxSearchResults = 200
 12→
 13→// Vault represents an Obsidian vault directory with path validation
 14→type Vault struct {
 15→	Path string // resolved absolute path to the vault root
 16→}
 17→
 18→// New creates a new Vault, expanding ~ and resolving to an absolute path.
 19→// Returns an error if the vault directory does not exist.
 20→func New(rawPath string) (*Vault, error) {
 21→	path := rawPath
 22→
 23→	// Expand home directory
 24→	if strings.HasPrefix(path, "~") {
 25→		home, err := os.UserHomeDir()
 26→		if err != nil {
 27→			return nil, fmt.Errorf("failed to get home directory: %w", err)
 28→		}
 29→		path = filepath.Join(home, path[1:])
 30→	}
 31→
 32→	// Check if vault path exists
 33→	if _, err := os.Stat(path); os.IsNotExist(err) {
 34→		return nil, fmt.Errorf("vault path does not exist: %s", path)
 35→	}
 36→
 37→	return &Vault{Path: path}, nil
 38→}
 39→
 40→// IsPathAllowed checks if a given path is within the allowed vault directory
 41→// and doesn't access hidden files or directories
 42→func (v *Vault) IsPathAllowed(path string) (bool, error) {
 43→	// Expand home directory
 44→	if strings.HasPrefix(path, "~") {
 45→		home, err := os.UserHomeDir()
 46→		if err != nil {
 47→			return false, fmt.Errorf("failed to get home directory: %w", err)
 48→		}
 49→		path = filepath.Join(home, path[1:])
 50→	}
 51→
 52→	// Get absolute path
 53→	absPath, err := filepath.Abs(path)
 54→	if err != nil {
 55→		return false, fmt.Errorf("failed to get absolute path: %w", err)
 56→	}
 57→
 58→	// Resolve symlinks
 59→	resolvedPath, err := filepath.EvalSymlinks(absPath)
 60→	if err != nil {
 61→		// If the path doesn't exist, walk up to the nearest existing
 62→		// ancestor, resolve its symlinks, then re-append the remainder.
 63→		if os.IsNotExist(err) {
 64→			resolvedPath = resolveWithAncestors(absPath)
 65→		} else {
 66→			return false, fmt.Errorf("failed to resolve symlinks: %w", err)
 67→		}
 68→	}
 69→
 70→	// Get absolute vault path
 71→	absVaultPath, err := filepath.Abs(v.Path)
 72→	if err != nil {
 73→		return false, fmt.Errorf("failed to get absolute vault path: %w", err)
 74→	}
 75→
 76→	// Resolve vault symlinks
 77→	resolvedVaultPath, err := filepath.EvalSymlinks(absVaultPath)
 78→	if err != nil {
 79→		if !os.IsNotExist(err) {
 80→			return false, fmt.Errorf("failed to resolve vault symlinks: %w", err)
 81→		}
 82→		resolvedVaultPath = resolveWithAncestors(absVaultPath)
 83→	}
 84→
 85→	// Clean paths
 86→	cleanPath := filepath.Clean(resolvedPath)
 87→	cleanVaultPath := filepath.Clean(resolvedVaultPath)
 88→
 89→	// Check if path is within vault
 90→	if !strings.HasPrefix(cleanPath, cleanVaultPath) {
 91→		return false, nil
 92→	}
 93→
 94→	// Check for hidden files/directories
 95→	relPath, err := filepath.Rel(cleanVaultPath, cleanPath)
 96→	if err != nil {
 97→		return false, fmt.Errorf("failed to get relative path: %w", err)
 98→	}
 99→
100→	pathParts := strings.SplitSeq(relPath, string(filepath.Separator))
101→	for part := range pathParts {
102→		if strings.HasPrefix(part, ".") && part != "." && part != ".." {
103→			return false, nil
104→		}
105→	}
106→
107→	return true, nil
108→}
109→
110→// resolveWithAncestors resolves symlinks by walking up to the nearest existing
111→// ancestor directory and re-appending the remaining path segments.
112→func resolveWithAncestors(absPath string) string {
113→	current := absPath
114→	var tail []string
115→	for {
116→		resolved, err := filepath.EvalSymlinks(current)
117→		if err == nil {
118→			// Found an existing ancestor — rejoin the tail
119→			for i := len(tail) - 1; i >= 0; i-- {
120→				resolved = filepath.Join(resolved, tail[i])
121→			}
122→			return resolved
123→		}
124→		parent := filepath.Dir(current)
125→		if parent == current {
126→			// Reached filesystem root without finding existing path
127→			return absPath
128→		}
129→		tail = append(tail, filepath.Base(current))
130→		current = parent
131→	}
132→}
