291→// DeleteNote implements the delete_note tool
292→func (h *Handler) DeleteNote(ctx context.Context, req *mcp.CallToolRequest, input note.DeleteNoteInput) (*mcp.CallToolResult, note.DeleteNoteOutput, error) {
293→	if !strings.HasSuffix(strings.ToLower(input.Path), ".md") {
294→		return nil, note.DeleteNoteOutput{}, fmt.Errorf("can only delete .md files")
295→	}
296→
297→	allowed, err := h.vault.IsPathAllowed(input.Path)
298→	if err != nil {
299→		return nil, note.DeleteNoteOutput{}, fmt.Errorf("path validation error: %w", err)
300→	}
301→	if !allowed {
302→		return nil, note.DeleteNoteOutput{}, fmt.Errorf("access denied: path is outside vault or is a hidden file")
303→	}
304→
305→	info, err := os.Stat(input.Path)
306→	if os.IsNotExist(err) {
307→		return nil, note.DeleteNoteOutput{}, fmt.Errorf("file does not exist: %s", input.Path)
308→	}
309→	if err != nil {
310→		return nil, note.DeleteNoteOutput{}, fmt.Errorf("failed to stat file: %w", err)
311→	}
312→	if info.IsDir() {
313→		return nil, note.DeleteNoteOutput{}, fmt.Errorf("cannot delete directories")
314→	}
315→
316→	if err := os.Remove(input.Path); err != nil {
317→		return nil, note.DeleteNoteOutput{}, fmt.Errorf("failed to delete file: %w", err)
318→	}
319→
320→	output := note.DeleteNoteOutput(input)
321→	result := &mcp.CallToolResult{
322→		Content: []mcp.Content{
323→			&mcp.TextContent{Text: fmt.Sprintf("Deleted note: %s", input.Path)},
324→		},
325→	}
326→	return result, output, nil
327→}
